import { Router } from 'express';
import requireAuth from '../../middleware/requireAuth.js';
import { createReport } from './reports.controller.js';

const router = Router();

// The single POST report endpoint. Mounted at /api/reports in app.js.
// Contract: backend/API.md, "reports module (Phase 7)". The review queue that
// consumes these reports is a separate module (admin, Phase 9, Vishwajeet).
router.post('/', requireAuth, createReport);

export default router;
